from collections import deque

def shortest_path(graph, source, target):
    if target not in graph:
        return float("inf"), None

    queue = deque([(source, [source])])  # Queue to perform BFS
    visited = set()  # Visited nodes to avoid cycles

    while queue:
        current, path = queue.popleft()
        if current == target:
            return len(path) - 1, path  # Subtract 1 because index starts from 0
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                queue.append((neighbor[0], path + [neighbor[0]]))

    return float("inf"), None  # Return infinity if target is unreachable

